SaveToggle {
    saved: saved.read().contains(&title),
    icon: HEART_ICON.to_string(),
    ontoggle: move |next: bool| {
        let mut list = saved.write();
        if next { list.push(title) } else { list.retain(|t| *t != title) }
    },
    if saved.read().contains(&title) { "Saved" } else { "Save" }
}

